  const ls = {
    get(k, d) { try { const v = JSON.parse(localStorage.getItem(k)); return v === null || v === undefined ? d : v; } catch (e) { return d; } },
    set(k, v) { try { localStorage.setItem(k, JSON.stringify(v)); } catch (e) {} },
    del(k) { try { localStorage.removeItem(k); } catch (e) {} },
  };
  const byId = (id) => P.find((p) => p.id === +id);

  /* ------------------------------------------------------------ sign-in demo state (kept between pages) */
  if (ls.get('sero.signed', false)) document.body.classList.add('signed-in');
  const so = $('#sOut'), si = $('#sIn');
  if (so && si) { so.addEventListener('click', () => { ls.set('sero.signed', false); document.dispatchEvent(new CustomEvent('sero:auth')); }); si.addEventListener('click', () => { ls.set('sero.signed', true); document.dispatchEvent(new CustomEvent('sero:auth')); }); }
  if (so && si) { const on = document.body.classList.contains('signed-in'); so.setAttribute('aria-pressed', String(!on)); si.setAttribute('aria-pressed', String(on)); }

